#!/usr/bin/env python3
"""Reproduce complete mesh sources from complete literal bodies; stdlib only.

No generated module is imported, no scientific or mesh expression is evaluated.
This file verifies full source bytes and syntax and writes complete standalone
sources. It is not a scientific admission fixture.
"""
from __future__ import annotations
import argparse
import ast
import hashlib
import json
from pathlib import Path

TOPIC = "topics/visible-flex-larger-amplitude"
def sha_bytes(value):
    return hashlib.sha256(value).hexdigest()

def whole(path, expected):
    raw = Path(path).read_bytes()
    if sha_bytes(raw) != expected:
        raise ValueError("Complete source differs: "+str(path))
    return raw.decode("utf-8")

def assignment(text, name):
    tree = ast.parse(text)
    values = [n.value for n in tree.body if isinstance(n,ast.Assign)
        and any(isinstance(t,ast.Name) and t.id==name for t in n.targets)]
    if len(values)!=1:
        raise ValueError("Require one literal "+name)
    return ast.literal_eval(values[0])

def function_body(text, name):
    node = next(n for n in ast.parse(text).body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))
        and n.name==name)
    return "\n".join(text.splitlines()[node.lineno-1:node.end_lineno])

def emit(args):
    result=[]
    args.output_dir.mkdir(parents=True,exist_ok=True)
    for name,value in EMBEDDED.items():
        text=value["text"]
        data=text.encode("utf-8")
        if len(data)!=value["bytes"] or sha_bytes(data)!=value["sha256"]:
            raise ValueError("Embedded complete body differs: "+name)
        ast.parse(text,filename=name)
        compile(text,name,"exec",dont_inherit=True)
        path=args.output_dir/name
        if args.verify_existing:
            if path.read_bytes()!=data:
                raise ValueError("The complete existing source differs: "+name)
        elif path.exists():
            if path.read_bytes()!=data:
                raise FileExistsError("Do not overwrite a different existing complete source")
        else:
            path.write_bytes(data)
        if path.read_bytes()!=data:
            raise ValueError("Complete source output changed")
        result.append(dict(name=name,sha256=sha_bytes(data),bytes=len(data)))
    return result

def parse():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument("--repo",type=Path,required=True)
    p.add_argument("--output-dir",type=Path,required=True)
    p.add_argument("--verify-existing",action="store_true")
    a=p.parse_args()
    a.repo=a.repo.resolve();a.output_dir=a.output_dir.resolve()
    return a

